def is_palindrome(s: str) -> bool:
    """Verify whether a string is a palindrome, ignoring non-alphanumeric chars and case."""
    cleaned = [ch.lower() for ch in s if ch.isalnum()]
    left, right = 0, len(cleaned) - 1
    while left < right:
        if cleaned[left] != cleaned[right]:
            return False
        left += 1
        right -= 1
    return True
